import openpyxl
ip='/tmp/llm_rollout_x8yw3r7b/2_59969_answer_template_3160_input.xlsx'
gp='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/2_59969_answer_template_3160_golden.xlsx'
wi=openpyxl.load_workbook(ip, data_only=False)
wg=openpyxl.load_workbook(gp, data_only=False)
diffs=0
for wsname in wg.sheetnames:
    wi_ws=wi[wsname]; wg_ws=wg[wsname]
    for r in range(1, wg_ws.max_row+1):
        for c in range(1, wg_ws.max_column+1):
            vi=wi_ws.cell(row=r,column=c).value
            vg=wg_ws.cell(row=r,column=c).value
            if hasattr(vi,'text'): vi=('AF',vi.text,vi.ref)
            if hasattr(vg,'text'): vg=('AF',vg.text,vg.ref)
            if vi!=vg:
                print('DIFF', wsname, wi_ws.cell(row=r,column=c).coordinate, repr(vi), repr(vg))
                diffs+=1
print('total diffs',diffs)
